/** REGION_CLUSTERS (flatten Indonesia). */
export const REGION_CLUSTERS = COUNTRIES.find((c) => c.id === 'ID')?.regions.map((r) => ({
  region: r.nameId,
  cities: r.cities.map((c) => ({ name: c.name, province: c.provinceId, subDistricts: c.subDistricts }))
})) || [];

export function cityMeta(cityName) {
  const needle = String(cityName || '').toLowerCase();
  for (const country of COUNTRIES) {
    for (const region of country.regions) {
      for (const city of region.cities) {
        if (city.name.toLowerCase() === needle) {
          return { country: country.id, region: region.nameId, city: city.name, province: city.provinceId, subDistricts: city.subDistricts || [] };
        }
      }
    }
  }
  return null;
}

export function keywordsForCategory(catId, lang = 'id') {
  for (const sector of CATEGORY_SECTORS) {
    const hit = sector.categories.find((c) => c.id === catId);
    if (hit) return lang === 'en' ? hit.keywordsEn : hit.keywordsId;
  }
  return [];
}

export function labelForCategory(catId, lang = 'id') {
  for (const sector of CATEGORY_SECTORS) {
    const hit = sector.categories.find((c) => c.id === catId);
    if (hit) return lang === 'en' ? hit.labelEn : hit.labelId;
  }
  return catId;
}

/**
 * CRM Leads Store - GMaps CRM Pro
 *
 * Penyimpanan file JSON lokal (tanpa database eksternal):
 * - leads: calon pembeli (dari Finder, import file, atau input manual)
 * - activities: riwayat tindak lanjut per lead
 * - templates: pola pesan siap pakai (bilingual)
 *
 * Dedup: placeId dulu, lalu nomor HP dinormalisasi + nama.
 */

import fs from 'fs';
import path from 'path';
import crypto from 'crypto';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

export const STAGES = [
  { id: 'baru', labelId: 'Baru', labelEn: 'New' },
  { id: 'dihubungi', labelId: 'Sudah Dihubungi', labelEn: 'Contacted' },
  { id: 'tindak_lanjut', labelId: 'Tindak Lanjut', labelEn: 'Follow-up' },
  { id: 'negosiasi', labelId: 'Negosiasi', labelEn: 'Negotiating' },
  { id: 'deal', labelId: 'Berhasil (Deal)', labelEn: 'Won' },
  { id: 'gagal', labelId: 'Gagal', labelEn: 'Lost' }
];

const CLOSED_STAGES = new Set(['deal', 'gagal']);

export function crmFilePath() {
  return process.env.CRM_FILE || path.join(__dirname, '..', 'crm-data.json');
}

function blankStore() {
  return { version: 1, leads: [], activities: [], templates: defaultTemplates() };
}

export function defaultTemplates() {
  return [
    {
      id: 'salam-kenal',
      nameId: 'Salam kenal',
