  { header: 'Koordinat', key: 'coordinates', width: 24 }
];

const CRM_COLUMNS = [
  { header: 'Nama Calon Pembeli', key: 'name', width: 32 },
  { header: 'Telepon', key: 'phone', width: 20 },
  { header: 'Kota', key: 'city', width: 18 },
