const STAGE_LABEL = {
  id: { baru: 'Baru', dihubungi: 'Sudah Dihubungi', tindak_lanjut: 'Tindak Lanjut', negosiasi: 'Negosiasi', deal: 'Berhasil', gagal: 'Gagal' },
