      toast((uiLang === 'en' ? 'Failed: ' : 'Gagal: ') + e.message + (uiLang === 'en' ? ' Is the app server running?' : ' Pastikan server aplikasi berjalan.'), 'error');
    } finally {
      btn.disabled = false;
    }
  });
  $('btnDeactivateLicense').addEventListener('click', async () => {
    if (!confirm('Nonaktifkan lisensi di perangkat ini?')) return;
    const res = await fetch('/api/license/deactivate', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{}' });
    licenseState = (await res.json()).status;
    renderLicense();
  });
  $('btnCopyInstallId').addEventListener('click', () => navigator.clipboard?.writeText(licenseState?.installId || '').then(() => toast('Disalin')));
  $('btnVerifyQuickReff').addEventListener('click', async () => {
    const reff = ($('inputQuickReff').value || '').trim();
    if (!reff) return;
    try {
      const res = await fetch('/api/payment/auto-activate', {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ reff })
      });
      const data = await res.json();
      if (!data.found) throw new Error(data.message || 'Belum ditemukan');
      licenseState = data.status;
      renderLicense();
      toast(uiLang === 'en' ? 'Active!' : 'Aktif!', 'success');
    } catch (e) { toast(e.message, 'error'); }
  });

  $('btnSettingsMenu').addEventListener('click', (e) => {
    e.stopPropagation();
    const m = $('settingsMenu');
    m.hidden = !m.hidden;
  });
  document.addEventListener('click', () => { $('settingsMenu').hidden = true; });
  $('menuLicense').addEventListener('click', () => $('licensePill').click());
  $('menuLang').addEventListener('click', () => { uiLang = uiLang === 'id' ? 'en' : 'id'; localStorage.setItem('gcrm-lang', uiLang); applyLang(); });
  $('menuAbout').addEventListener('click', () => {
    $('aboutInstallId').textContent = licenseState?.installId || '-';
    $('aboutLicenseState').textContent = licenseState?.activated ? 'Aktif' : 'Trial';
    $('aboutModal').hidden = false;
  });
  $('btnAboutClose').addEventListener('click', () => { $('aboutModal').hidden = true; });
  $('menuExit').addEventListener('click', () => {
    if (window.electronAPI) window.electronAPI.windowControl('close');
    else toast(uiLang === 'en' ? 'Just close this tab.' : 'Tutup tab ini saja.', 'info');
  });

  if (window.electronAPI) {
    document.body.classList.add('electron');
    $('appTitlebar').hidden = false;
    $('winMinimize').addEventListener('click', () => window.electronAPI.windowControl('minimize'));
    $('winMaximize').addEventListener('click', () => window.electronAPI.windowControl('maximize'));
    $('winClose').addEventListener('click', () => window.electronAPI.windowControl('close'));
  }
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') { closeDrawer(); $('aboutModal').hidden = true; }
  });
});

/* Hallmark · macrostructure: Workbench · tone: modern-minimal elegan · anchor hue: cool-blue */
/* GMaps CRM Pro - elegan, compact, melebar. Bahasa ramah non-teknis. */
:root {
  --color-paper: #f6f8fc;
  --color-card: #ffffff;
  --color-ink: #0f1e33;
  --color-ink-2: #3d4f6b;
  --color-muted: #8494ab;
  --color-line: #e3e9f3;
  --color-accent: #1d4ed8;
  --color-accent-2: #0ea5e9;
  --color-ok: #059669;
  --color-warn: #d97706;
  --color-bad: #dc2626;
  --color-chip: #eef3fd;
  --radius: 14px;
  --radius-sm: 9px;
  --space-xs: 4px;
  --space-sm: 8px;
  --space-md: 16px;
  --space-lg: 24px;
  --space-xl: 36px;
  --font-body: "Segoe UI", system-ui, -apple-system, sans-serif;
  --ease-out: cubic-bezier(0.22, 1, 0.36, 1);
  --dur: 220ms;
}
* { box-sizing: border-box; }
html, body { overflow-x: clip; }
body {
  margin: 0;
  font-family: var(--font-body);
  background: linear-gradient(180deg, #eef2f9 0%, var(--color-paper) 240px);
  color: var(--color-ink);
  min-height: 100vh;
}
button { font-family: inherit; cursor: pointer; }
h2 { font-size: 1.02rem; margin: 0 0 var(--space-sm); font-weight: 700; }
h3 { font-size: 0.92rem; margin: var(--space-md) 0 var(--space-sm); }
.hint { color: var(--color-muted); font-size: 0.8rem; margin: var(--space-xs) 0; }
.error { color: var(--color-bad); font-size: 0.82rem; }

/* Titlebar Electron */
#appTitlebar { display: none; }
body.electron #appTitlebar {
  display: flex; justify-content: space-between; align-items: center;
  background: #0f1e33; color: #fff; padding: 6px 12px;
  -webkit-app-region: drag; user-select: none;
}
body.electron #appTitlebar button { -webkit-app-region: no-drag; }
.tb-brand { display: flex; gap: 8px; align-items: center; font-size: 0.82rem; font-weight: 600; }
.tb-dot { width: 9px; height: 9px; border-radius: 50%; background: linear-gradient(135deg, var(--color-accent), var(--color-accent-2)); }
.tb-license { font-weight: 400; opacity: 0.75; }
.tb-controls button { background: transparent; border: none; color: #fff; padding: 4px 10px; border-radius: 6px; }
.tb-controls button:hover { background: rgba(255,255,255,0.15); }

/* Topbar */
.topbar {
  display: flex; align-items: center; gap: var(--space-md);
  padding: 10px var(--space-lg);
  background: rgba(255,255,255,0.86); backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--color-line);
  position: sticky; top: 0; z-index: 30;
}
.brand { display: flex; gap: 10px; align-items: center; min-width: 220px; }
.brand-logo { border-radius: 10px; box-shadow: 0 4px 12px rgba(234,67,53,0.3); }
.brand-mark {
  width: 36px; height: 36px; border-radius: 11px; color: #fff; font-weight: 800; font-size: 1.2rem;
  display: grid; place-items: center;
  background: linear-gradient(135deg, var(--color-accent), var(--color-accent-2));
  box-shadow: 0 6px 16px rgba(29,78,216,0.3);
}
.brand-name { font-weight: 800; font-size: 0.95rem; }
.brand-sub { font-size: 0.72rem; color: var(--color-muted); }
.tabs { display: flex; gap: 6px; flex: 1; flex-wrap: wrap; align-items: flex-end; position: relative; }
.tabs::after {
  content: ''; position: absolute; left: 0; right: 0; bottom: -11px; height: 2px;
  background: var(--color-line); pointer-events: none;
}
.nav-tab-btn {
  border: 1px solid var(--color-line); border-bottom: none; background: #e9edf4;

  padding: 9px 16px 10px; border-radius: 11px 11px 0 0;
  font-size: 0.84rem; color: var(--color-ink-2); font-weight: 600;
  transition: background var(--dur) var(--ease-out), color var(--dur) var(--ease-out), transform var(--dur) var(--ease-out), box-shadow var(--dur) var(--ease-out);
  display: inline-flex; align-items: center; gap: 8px;
  position: relative; z-index: 0;
}
.nav-tab-btn:hover { background: #f2f5fa; transform: translateY(-2px); }
.nav-tab-btn:hover .tab-icon-wrap { transform: scale(1.06); }
.nav-tab-btn.active {
  background: #fff; color: var(--tab-accent, var(--color-ink)); font-weight: 800;
  z-index: 1; margin-bottom: -11px; padding-bottom: 21px;
  box-shadow: 0 -6px 14px rgba(15,30,51,0.07);
}
.nav-tab-btn.active::before {
  content: ''; position: absolute; top: -1px; left: 12px; right: 12px; height: 4px;
  border-radius: 0 0 5px 5px; background: var(--tab-accent, var(--color-accent));
}
@media (prefers-reduced-motion: reduce) {
  .nav-tab-btn, .nav-tab-btn:hover { transform: none; }
  .tab-content.active { animation: none; }
}
.tab-icon-wrap {
  display: inline-flex; align-items: center; justify-content: center;
  width: 22px; height: 22px; border-radius: 6px; flex-shrink: 0;
  transition: transform 150ms ease;
}
.top-actions { display: flex; gap: 8px; align-items: center; position: relative; }
.lang-switch { display: flex; border: 1px solid var(--color-line); border-radius: 999px; overflow: hidden; }
.lang-switch button { border: none; background: transparent; padding: 6px 12px; font-size: 0.76rem; font-weight: 700; color: var(--color-muted); }
.lang-switch button.active { background: var(--color-accent); color: #fff; }
.license-pill { display: flex; gap: 7px; align-items: center; border: 1px solid var(--color-line); background: #fff; border-radius: 999px; padding: 6px 12px; font-size: 0.78rem; }
.license-dot { width: 9px; height: 9px; border-radius: 50%; background: var(--color-muted); }
.license-dot.ok { background: var(--color-ok); box-shadow: 0 0 0 4px rgba(5,150,105,0.15); }
.license-dot.warn { background: var(--color-warn); }
.license-dot.bad { background: var(--color-bad); }
.menu { position: absolute; right: 0; top: 42px; background: #fff; border: 1px solid var(--color-line); border-radius: 12px; box-shadow: 0 16px 40px rgba(15,30,51,0.14); min-width: 190px; padding: 6px; z-index: 50; }
.menu button { display: block; width: 100%; text-align: left; border: none; background: transparent; padding: 9px 12px; border-radius: 8px; font-size: 0.84rem; }
.menu button:hover { background: var(--color-chip); }

main { padding: var(--space-lg); max-width: 1720px; margin: 0 auto; }
.tab-content { display: none; }
.tab-content.active { display: block; animation: folderIn 280ms var(--ease-out); transform-origin: top center; }
@keyframes fadeUp { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: none; } }
@keyframes folderIn {
  from { opacity: 0; transform: perspective(1100px) rotateX(-5deg) translateY(12px); }
  to { opacity: 1; transform: perspective(1100px) rotateX(0) translateY(0); }
}

.panel { background: var(--color-card); border: 1px solid var(--color-line); border-radius: var(--radius); padding: var(--space-lg); box-shadow: 0 2px 10px rgba(15,30,51,0.05); }
.panel.wide { padding: var(--space-md) var(--space-lg); }

/* Workbench: form compact + live lebar */
.workbench { display: grid; grid-template-columns: 380px minmax(0, 1fr); gap: var(--space-md); align-items: start; }
.field { display: block; margin-bottom: var(--space-sm); font-size: 0.82rem; }
.field > span { display: block; font-weight: 600; margin-bottom: 4px; color: var(--color-ink-2); }
.field input, .field select, .field textarea, .crm-head-actions input, .template-row select, .quick-reff input, .activity-add input {
  width: 100%; border: 1px solid var(--color-line); border-radius: var(--radius-sm);
  padding: 8px 10px; font-size: 0.84rem; font-family: inherit; background: #fbfcfe;
}
.field input:focus, .field select:focus { outline: 2px solid var(--color-accent); border-color: var(--color-accent); }
.field.check { display: flex; gap: 8px; align-items: center; }
.field.check input { width: auto; }
.row-2 { display: grid; grid-template-columns: 1fr 1fr; gap: var(--space-sm); }

/* Sectors compact: kecil, rapat, bikin layar melebar */
.sectors.compact { display: flex; flex-direction: column; gap: 6px; max-height: 260px; overflow: auto; border: 1px solid var(--color-line); border-radius: var(--radius-sm); padding: 8px; background: #fbfcfe; }
.sector-group-label { font-size: 0.68rem; font-weight: 800; text-transform: uppercase; color: var(--color-muted); letter-spacing: 0.04em; }
.pill-container { display: flex; flex-wrap: wrap; gap: 5px; margin-bottom: 4px; }
.category-pill, .city-pill, .country-pill {
  font-size: 0.72rem; padding: 4px 10px; border-radius: 999px; border: 1px solid var(--color-line);
  background: #fff; cursor: pointer; transition: all 140ms var(--ease-out); white-space: nowrap;
}
.category-pill:hover, .city-pill:hover, .country-pill:hover { border-color: var(--color-accent); }
.category-pill.selected, .city-pill.selected, .country-pill.selected { background: var(--color-accent); border-color: var(--color-accent); color: #fff; font-weight: 700; }
.regions.compact { max-height: 220px; overflow: auto; border: 1px solid var(--color-line); border-radius: var(--radius-sm); padding: 8px; background: #fbfcfe; display: flex; flex-direction: column; gap: 6px; }
.scope-hint { font-size: 0.76rem; color: var(--color-ink-2); background: var(--color-chip); border-radius: var(--radius-sm); padding: 8px 10px; }

.btn { border: 1px solid var(--color-line); background: #fff; border-radius: var(--radius-sm); padding: 9px 16px; font-size: 0.84rem; font-weight: 600; transition: all 150ms var(--ease-out); text-decoration: none; display: inline-block; color: var(--color-ink); }
.btn:hover { transform: translateY(-1px); box-shadow: 0 6px 14px rgba(15,30,51,0.1); }
.btn:active { transform: none; }
.btn.primary { background: linear-gradient(135deg, var(--color-accent), var(--color-accent-2)); border: none; color: #fff; }
.btn.danger { background: var(--color-bad); border: none; color: #fff; }
.btn.ghost { background: transparent; }
.btn:disabled { opacity: 0.5; cursor: not-allowed; transform: none; box-shadow: none; }
.danger-text { color: var(--color-bad); }
.finder-actions { display: flex; gap: 8px; }

/* Live panel */
.live-head { display: flex; justify-content: space-between; align-items: center; }
.tag { font-size: 0.72rem; font-weight: 700; padding: 4px 10px; border-radius: 999px; background: var(--color-chip); color: var(--color-ink-2); }
.tag-emerald, .tag-ok { background: #dcfce7; color: #047857; }
.tag-amber { background: #fef3c7; color: #92400e; }
.tag-blue { background: #dbeafe; color: #1d4ed8; }
.scan-visual { position: relative; height: 74px; border-radius: var(--radius-sm); background: linear-gradient(180deg, #eef4ff, #f8fbff); border: 1px solid var(--color-line); overflow: hidden; margin: var(--space-sm) 0; }
.scan-line { position: absolute; left: 0; right: 0; height: 3px; top: 0; background: linear-gradient(90deg, transparent, var(--color-accent-2), transparent); opacity: 0.25; }
.scan-pin { position: absolute; left: 50%; top: 50%; transform: translate(-50%, -50%); font-size: 1.6rem; filter: grayscale(1); opacity: 0.5; }
.scanning .scan-line { opacity: 1; animation: scan 2.2s var(--ease-out) infinite; }
.scanning .scan-pin { filter: none; opacity: 1; animation: bob 1.1s ease-in-out infinite; }
@keyframes scan { 0% { top: 0; } 50% { top: calc(100% - 3px); } 100% { top: 0; } }
@keyframes bob { 0%, 100% { transform: translate(-50%, -50%); } 50% { transform: translate(-50%, -62%); } }
.progress-meta { display: flex; justify-content: space-between; font-size: 0.8rem; font-weight: 700; }
.progress-track { height: 10px; background: #e8edf5; border-radius: 999px; overflow: hidden; margin: 6px 0; }
.progress-fill { height: 100%; width: 0; border-radius: 999px; background: linear-gradient(90deg, var(--color-accent), var(--color-accent-2)); transition: width 400ms var(--ease-out); }
.status-line { font-size: 0.84rem; color: var(--color-ink-2); }
.console { background: #0b1526; color: #c9e2ff; border-radius: var(--radius-sm); padding: 12px; font-size: 0.74rem; max-height: 220px; overflow: auto; white-space: pre-wrap; }
.console.small { max-height: 110px; }
.live-actions { display: flex; gap: 8px; margin-top: var(--space-sm); }

/* Results KPI strip */
.kpi-row { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px; margin: var(--space-sm) 0 var(--space-md); }
@media (max-width: 1100px) { .kpi-row { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (max-width: 640px) { .kpi-row { grid-template-columns: 1fr; } }
.kpi-card {
  background: var(--color-card); border: 1px solid var(--color-line); border-radius: var(--radius);
  padding: 12px 16px; box-shadow: 0 2px 10px rgba(15,30,51,0.05);
  transition: transform var(--dur) var(--ease-out), box-shadow var(--dur) var(--ease-out);
}
.kpi-card:hover { transform: translateY(-1px); box-shadow: 0 8px 22px rgba(15,30,51,0.10); }
.kpi-header { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.kpi-title { font-size: 0.68rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.05em; color: var(--color-muted); }
.kpi-icon { display: inline-flex; opacity: 0.9; }
.kpi-number { font-size: 1.55rem; font-weight: 800; letter-spacing: -0.03em; font-variant-numeric: tabular-nums; line-height: 1.2; margin-top: 2px; }
.kpi-caption { font-size: 0.72rem; color: var(--color-muted); font-weight: 500; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

/* Results action bar: exports + title block */
.results-actions {
  display: flex;
  gap: 8px;
  align-items: center;
  flex-wrap: wrap;
}
.btn-ghost {
  background: transparent;
  border: 1px solid var(--color-line);
  color: var(--color-ink);
  padding: 6px 10px;
  border-radius: var(--radius-sm);
  font-size: 0.8rem;
  cursor: pointer;
}
.btn-ghost:hover { background: #f1f5fb; }

/* Keep table compact and clean */
.wide-table .explorer-table th { padding: 8px; }
.wide-table .explorer-table td { padding: 8px; }
.explorer-table .cell-contact .actions { display: inline-flex; gap: 6px; align-items: center; }

/* Results: header rapi & compact */
.results-head {
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
  margin-bottom: var(--space-sm);
  padding-bottom: var(--space-sm);
  border-bottom: 1px solid var(--color-line);
}
.results-title-group h2 { margin: 0; line-height: 1.2; }
.results-title-group .hint { margin: 2px 0 0; }
.compact-filters {
  display: flex;
  gap: 8px;
  align-items: center;
  flex-wrap: wrap;
  justify-content: flex-end;
}
.compact-filters input, .compact-filters select {
  border: 1px solid var(--color-line);
  border-radius: var(--radius-sm);
  padding: 7px 11px;
  font-size: 0.8rem;
  background: #fbfcfe;
}
.compact-filters input { min-width: 200px; }
.compact-filters select { max-width: 170px; }
.compact-filters .check {
  display: inline-flex;
  gap: 6px;
  align-items: center;
  font-size: 0.8rem;
  cursor: pointer;
  user-select: none;
  white-space: nowrap;
}
.table-wrap { overflow: auto; border: 1px solid var(--color-line); border-radius: var(--radius-sm); margin-top: var(--space-sm); }
.wide-table table { min-width: 1180px; }
.explorer-table { width: 100%; border-collapse: collapse; font-size: 0.82rem; }
.explorer-table th { background: #0f1e33; color: #fff; padding: 10px; text-align: left; position: sticky; top: 0; white-space: nowrap; }
.explorer-table td { padding: 9px 10px; border-bottom: 1px solid var(--color-line); vertical-align: top; text-align: left; }
.explorer-table .cell-name { font-weight: 700; text-align: left; }
.explorer-table .cell-sub { font-size: 0.72rem; color: var(--color-muted); text-align: left; }
.explorer-table .cell-cat { max-width: 260px; min-width: 150px; text-align: left; }
.explorer-table .cat-tag {
  display: inline-block;
  max-width: 100%;
  overflow: visible;
  white-space: normal;
  word-break: break-word;
  line-height: 1.35;
  text-align: left;
}
.explorer-table .cell-contact { white-space: nowrap; text-align: left; }
.explorer-table .cell-rating { white-space: nowrap; text-align: left; }
.explorer-table .cell-actions { white-space: nowrap; text-align: left; }
.explorer-table tbody tr { transition: background 120ms; }
.explorer-table tbody tr:hover { background: #f2f6fd; cursor: pointer; }
.phone-badge { background: #e8f7ef; color: #047857; font-weight: 700; padding: 3px 9px; border-radius: 999px; font-size: 0.76rem; white-space: nowrap; }
.pagination { display: flex; gap: 8px; align-items: center; margin-top: var(--space-sm); }

/* CRM */
.crm-grid { display: grid; grid-template-columns: 300px minmax(0, 1fr); gap: var(--space-md); align-items: start; }
.reminders { display: flex; flex-direction: column; gap: 6px; max-height: 300px; overflow: auto; }
.reminder-card { border: 1px solid var(--color-line); border-left: 4px solid var(--color-warn); border-radius: var(--radius-sm); padding: 8px 10px; font-size: 0.78rem; cursor: pointer; background: #fffdf7; }
.reminder-card.overdue { border-left-color: var(--color-bad); background: #fff7f7; }
.reminder-card:hover { box-shadow: 0 4px 12px rgba(15,30,51,0.08); }
.funnel-mini { display: flex; flex-direction: column; gap: 5px; font-size: 0.78rem; }
.funnel-row { display: flex; justify-content: space-between; background: var(--color-chip); border-radius: 7px; padding: 5px 10px; }
.crm-side-actions { margin-top: var(--space-sm); }
.crm-head { display: flex; justify-content: space-between; gap: var(--space-sm); flex-wrap: wrap; align-items: center; }
.crm-head-actions { display: flex; gap: 8px; }
.crm-head-actions input { border: 1px solid var(--color-line); border-radius: var(--radius-sm); padding: 8px 10px; font-size: 0.82rem; }
.kanban { display: grid; grid-template-columns: repeat(6, minmax(210px, 1fr)); gap: 10px; margin-top: var(--space-sm); overflow-x: auto; padding-bottom: 6px; }
.kanban-col { background: #f1f5fb; border-radius: var(--radius-sm); padding: 8px; min-height: 300px; display: flex; flex-direction: column; gap: 8px; }
.kanban-col h4 { margin: 2px 4px 4px; font-size: 0.76rem; text-transform: uppercase; letter-spacing: 0.04em; color: var(--color-ink-2); display: flex; justify-content: space-between; }
.lead-card { background: #fff; border: 1px solid var(--color-line); border-radius: 10px; padding: 9px 10px; font-size: 0.78rem; cursor: grab; transition: all 150ms var(--ease-out); animation: fadeUp 200ms var(--ease-out); }
.lead-card:hover { box-shadow: 0 8px 18px rgba(15,30,51,0.1); transform: translateY(-1px); }
.lead-card.dragging { opacity: 0.5; }

.lead-card .lc-name { font-weight: 700; }
.lead-card .lc-meta { color: var(--color-muted); font-size: 0.72rem; }
.lead-card .lc-score { float: right; font-weight: 800; color: var(--color-warn); }
.kanban-col.dragover { outline: 2px dashed var(--color-accent); background: #e8effd; }

/* Charts */
.charts-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: var(--space-md); }
.bars { display: flex; flex-direction: column; gap: 8px; }
.bar-row { display: grid; grid-template-columns: minmax(0, 150px) minmax(0, 1fr) 56px; gap: 8px; align-items: center; font-size: 0.78rem; }
